CREATE TABLE workspace (id TEXT PRIMARY KEY, founder TEXT NOT NULL, schedule_json TEXT NOT NULL);
CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, tagline TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, job TEXT NOT NULL, soul TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'idle', last_run_at TEXT, last_runtime TEXT NOT NULL DEFAULT 'loop', budget_usd REAL NOT NULL DEFAULT 2);
CREATE TABLE channels (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, members_json TEXT NOT NULL, last_at TEXT, last_read_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL, author TEXT NOT NULL, text TEXT NOT NULL, created_at TEXT NOT NULL, held INTEGER NOT NULL DEFAULT 0, level TEXT, proposal_id TEXT, mentions_json TEXT NOT NULL DEFAULT '[]', refs_json TEXT NOT NULL DEFAULT '[]', run_id TEXT);
CREATE INDEX idx_messages_channel ON messages (channel_id, created_at);
CREATE TABLE proposals (id TEXT PRIMARY KEY, agent TEXT NOT NULL, product_id TEXT, kind TEXT NOT NULL, title TEXT NOT NULL, why TEXT NOT NULL, payload_json TEXT NOT NULL, payload_hash TEXT NOT NULL, status TEXT NOT NULL, level TEXT NOT NULL, created_at TEXT NOT NULL, decided_at TEXT, result_json TEXT, depends_on TEXT);
CREATE INDEX idx_proposals_status ON proposals (status, created_at);
CREATE TABLE activity (id TEXT PRIMARY KEY, at TEXT NOT NULL, agent TEXT NOT NULL, kind TEXT NOT NULL, summary TEXT NOT NULL, model TEXT, tokens_in INTEGER, tokens_out INTEGER, usd REAL, ms INTEGER, runtime TEXT, detail TEXT, run_id TEXT);
CREATE INDEX idx_activity_at ON activity (at);
CREATE INDEX idx_activity_agent ON activity (agent, at);
CREATE TABLE memories (id TEXT PRIMARY KEY, agent TEXT NOT NULL, text TEXT NOT NULL, source TEXT NOT NULL, embedding_json TEXT, created_at TEXT NOT NULL);
CREATE INDEX idx_memories_agent ON memories (agent, created_at);
CREATE TABLE standing_orders (id TEXT PRIMARY KEY, agent TEXT NOT NULL, text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE handovers (date TEXT PRIMARY KEY, json TEXT NOT NULL, decision_ids_json TEXT NOT NULL, generated_at TEXT NOT NULL);
CREATE TABLE shift_notes (id TEXT PRIMARY KEY, agent TEXT NOT NULL, run_id TEXT, text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_shift_notes_at ON shift_notes (created_at);
CREATE TABLE agent_runs (id TEXT PRIMARY KEY, agent TEXT NOT NULL, trigger TEXT NOT NULL, channel_id TEXT, started_at TEXT NOT NULL, finished_at TEXT, runtime TEXT, status TEXT NOT NULL);
CREATE INDEX idx_agent_runs_open ON agent_runs (agent, finished_at);
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, agent TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL, finished_at TEXT, error TEXT);
CREATE INDEX idx_jobs_status ON jobs (status, created_at);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE quarantine (id TEXT PRIMARY KEY, source TEXT NOT NULL, agent TEXT NOT NULL, excerpt TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE cron_runs (key TEXT PRIMARY KEY, at TEXT NOT NULL);
CREATE TABLE workday_runs (id TEXT PRIMARY KEY, status TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT);
